const listApplicationOnboardingApprovals = `-- name: ListApplicationOnboardingApprovals :many
SELECT id, application_id, kind, configuration_id, profile_revision, origin_epoch, source_epoch, application_revision, dispatch_revision, cohort_id, issuer_key_id, evidence_sha256, issued_at, expires_at, revoked_at, consumed_at FROM public.application_onboarding_approvals WHERE application_id=$1 ORDER BY id LIMIT 101
`

func (q *Queries) ListApplicationOnboardingApprovals(ctx context.Context, applicationID int64) ([]ApplicationOnboardingApproval, error) {
	rows, err := q.db.Query(ctx, listApplicationOnboardingApprovals, applicationID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ApplicationOnboardingApproval{}
	for rows.Next() {
		var i ApplicationOnboardingApproval
		if err := rows.Scan(
			&i.ID,
			&i.ApplicationID,
			&i.Kind,
			&i.ConfigurationID,
			&i.ProfileRevision,
			&i.OriginEpoch,
			&i.SourceEpoch,
			&i.ApplicationRevision,
			&i.DispatchRevision,
			&i.CohortID,
			&i.IssuerKeyID,
			&i.EvidenceSha256,
			&i.IssuedAt,
			&i.ExpiresAt,
			&i.RevokedAt,
			&i.ConsumedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

