const verifyApplicationFCMReservation = `-- name: VerifyApplicationFCMReservation :one
SELECT EXISTS(
    SELECT FROM public.application_onboarding_ingestions i
    JOIN public.applications a ON a.id=i.application_id
    JOIN public.application_onboarding o ON o.application_id=a.id
    JOIN public.staff_users s ON s.id=i.actor_id AND s.is_active AND s.auth_epoch=i.auth_epoch
    JOIN public.roles r ON r.id=s.role_id AND r.name='SUPER_ADMIN'
    JOIN public.staff_sessions f ON f.id=i.session_id AND f.staff_user_id=s.id AND f.auth_epoch=s.auth_epoch
    JOIN public.staff_session_control control ON control.singleton AND control.session_epoch=i.session_epoch
    WHERE a.public_id=$1::uuid AND i.id=$2::uuid
      AND i.configuration_id=$3::uuid AND i.environment=$4::text
      AND i.target_project_id=$5::text AND i.service_account_email=$6::text
      AND i.state='RESERVED' AND i.expires_at>clock_timestamp() AND a.status IN ('PROVISIONING','ACTIVE')
      AND i.expected_revision=o.revision AND f.session_epoch=control.session_epoch AND f.revoked_at IS NULL
      AND f.expires_at>clock_timestamp()
)
`

type VerifyApplicationFCMReservationParams struct {
	PublicID            pgtype.UUID `db:"public_id"`
	ReservationID       pgtype.UUID `db:"reservation_id"`
	ConfigurationID     pgtype.UUID `db:"configuration_id"`
	Environment         string      `db:"environment"`
	TargetProjectID     string      `db:"target_project_id"`
	ServiceAccountEmail string      `db:"service_account_email"`
}

func (q *Queries) VerifyApplicationFCMReservation(ctx context.Context, arg VerifyApplicationFCMReservationParams) (bool, error) {
	row := q.db.QueryRow(ctx, verifyApplicationFCMReservation,
		arg.PublicID,
		arg.ReservationID,
		arg.ConfigurationID,
		arg.Environment,
		arg.TargetProjectID,
		arg.ServiceAccountEmail,
	)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}
